// Project Infinity demo data — created THROUGH the business rules (plug-ins), so seeding also exercises them:
// projects go Draft → Pending → approved via pin_approval → Active; timesheets are submitted and approved;
// leave is applied for and approved; invoices are generated by the invoice engine.
// Usage: az login && node pi-dataverse/seed.mjs            (refuses to run twice; --force to add anyway)
import { api, log } from './lib.mjs';

const O = (i) => 543200000 + i;
const get = async (path) => (await api('GET', path, undefined, { solution: null })).value;
const sets = {};
async function setOf(logical) {
  sets[logical] ??= (await api('GET', `EntityDefinitions(LogicalName='${logical}')?$select=EntitySetName`, undefined, { solution: null })).EntitySetName;
  return sets[logical];
}
async function create(logical, body) {
  const set = await setOf(logical);
  const r = await api('POST', `${set}?$select=${logical}id`, body, { headers: { Prefer: 'return=representation' } });
  return r[`${logical}id`];
}
const update = async (logical, id, body) => api('PATCH', `${await setOf(logical)}(${id})`, body);
const bind = async (logical, id) => `/${await setOf(logical)}(${id})`;
const day = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * 86_400_000);
const monday = (d) => { const x = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())); return addDays(x, -((x.getUTCDay() + 6) % 7)); };
const TODAY = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));
const THIS_WEEK = monday(TODAY);

if ((await get('pin_projects?$select=pin_projectid&$top=1')).length && !process.argv.includes('--force')) {
  log('Projects already exist — refusing to seed twice (use --force).');
  process.exit(0);
}

